t.script:
/* Clinic slot picker: doctor + date -> free time buttons.
 * Writes the chosen local time ('YYYY-MM-DDTHH:MM') into a hidden "appointment_date" input. */
(function () {
    'use strict';

    function rpc(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params}),
        }).then(function (r) { return r.json(); }).then(function (d) { return d.result; });
    }

    window.ClinicSlotPicker = function (o) {
        var form = o.form, dateEl = o.dateInput, box = o.slotsBox;
        var hidden = o.hidden, timeEl = o.timeInput;
        var onChange = o.onChange || function () {};
        var seq = 0;

        function setValue(v) {
            hidden.value = v || '';
            onChange(hidden.value);
        }

        function doctorId() {
            var el = form.querySelector('input[name="doctor_id"]:checked') ||
                     form.querySelector('select[name="doctor_id"]');
            return el && el.value ? el.value : '';
        }

        function hint(text, cls) {
            box.innerHTML = '';
            var d = document.createElement('div');
            d.className = 'small ' + (cls || 'text-muted');
            d.textContent = text;
            box.appendChild(d);
        }

        function render(res) {
            timeEl.classList.add('d-none');
            if (!res) { return hint('Could not load available times. Please try again.', 'text-danger'); }

            if (!res.has_schedule) {
                // Doctor has no weekly schedule: let the patient pick any time
                hint('Pick your preferred time:');
                timeEl.classList.remove('d-none');
                return;
            }
            if (!res.slots.length) {
                return hint('No free slots on this date. Please choose another date.', 'text-danger');
            }
            box.innerHTML = '';
            res.slots.forEach(function (s) {
                var b = document.createElement('button');
                b.type = 'button';
                b.className = 'btn btn-outline-primary btn-sm m-1 cl-slot';
                b.textContent = s.label;
                b.addEventListener('click', function () {
                    box.querySelectorAll('.cl-slot').forEach(function (x) {
                        x.classList.remove('btn-primary');
                        x.classList.add('btn-outline-primary');
                    });
                    b.classList.remove('btn-outline-primary');
                    b.classList.add('btn-primary');
                    setValue(s.value);
                });
                box.appendChild(b);
            });
        }

        function refresh() {
            setValue('');
            timeEl.value = '';
            timeEl.classList.add('d-none');
            var doc = doctorId(), day = dateEl.value;
            if (!doc || !day) {
                return hint('Select a doctor and a date to see available times.');
            }
            hint('Loading available times...');
            var token = ++seq;
            rpc('/clinic/slots', {doctor_id: doc, date: day}).then(function (res) {
                if (token === seq) { render(res); }
            }).catch(function () {
                if (token === seq) { render(null); }
            });
        }

        form.addEventListener('change', function (e) {
            if (e.target === dateEl || e.target.name === 'doctor_id') { refresh(); }
        });
        timeEl.addEventListener('change', function () {
            setValue(timeEl.value && dateEl.value ? dateEl.value + 'T' + timeEl.value : '');
        });

        // Capture phase: runs before the page's own submit handlers (loading spinner etc.)
        form.addEventListener('submit', function (e) {
            if (!hidden.value) {
                e.preventDefault();
                e.stopImmediatePropagation();
                var warn = box.querySelector('.cl-slot-warn');
                if (!warn) {
                    warn = document.createElement('div');
                    warn.className = 'cl-slot-warn text-danger small mt-2';
                    warn.textContent = 'Please select a time slot.';
                    box.appendChild(warn);
                }
            }
        }, true);

        refresh();
    };
})();

(function () {
    'use strict';
    function $(s, c) { return (c || document).querySelector(s); }
    function $$(s, c) { return [].slice.call((c || document).querySelectorAll(s)); }
    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* ---- greeting by local time ---- */
    var greet = $('#pcGreet');
    if (greet) {
        var hr = new Date().getHours();
        greet.textContent = hr < 5 ? 'Hello' : hr < 12 ? 'Good morning' : hr < 18 ? 'Good afternoon' : 'Good evening';
    }

    /* ---- count-up numbers (one lightweight rAF loop, ~0.9s) ---- */
    var counters = $$('[data-count]');
    if (counters.length && !reduce) {
        var t0 = performance.now(), dur = 900;
        counters.forEach(function (el) { el.textContent = '0'; });
        (function tick(now) {
            var p = Math.min((now - t0) / dur, 1), e = 1 - Math.pow(1 - p, 3);
            counters.forEach(function (el) { el.textContent = Math.round((parseFloat(el.getAttribute('data-count')) || 0) * e); });
            if (p < 1) { requestAnimationFrame(tick); }
        })(t0);
    }

    /* ---- live countdown to the next appointment ---- */
    var cd = $('#pcCountdown');
    if (cd) {
        var target = new Date(cd.getAttribute('data-ts')).getTime(), label = cd.querySelector('span');
        var paint = function () {
            var diff = Math.floor((target - Date.now()) / 60000);
            if (isNaN(diff)) { cd.style.display = 'none'; return; }
            if (diff <= 0) { label.textContent = 'Happening now'; return; }
            var d = Math.floor(diff / 1440), h = Math.floor((diff % 1440) / 60), m = diff % 60;
            label.textContent = 'Starts in ' + (d ? d + 'd ' : '') + (d || h ? h + 'h ' : '') + m + 'm';
        };
        paint();
        setInterval(paint, 30000);
    }

    /* ---- small confetti burst after a successful booking ---- */
    if ($('.alert-success') && !reduce) {
        var box = document.createElement('div');
        box.className = 'pc-confetti';
        var colors = ['#0d9488', '#14b8a6', '#5eead4', '#fbbf24', '#fb7185', '#38bdf8'];
        for (var k = 0; k < 28; k++) {
            var piece = document.createElement('i');
            piece.style.setProperty('--bg', colors[k % colors.length]);
            piece.style.setProperty('--dx', (Math.random() * 480 - 240) + 'px');
            piece.style.setProperty('--dy', (Math.random() * 340 - 120) + 'px');
            piece.style.setProperty('--r', (Math.random() * 720 - 360) + 'deg');
            piece.style.animationDelay = (Math.random() * 120) + 'ms';
            box.appendChild(piece);
        }
        document.body.appendChild(box);
        setTimeout(function () { box.remove(); }, 2000);
    }

    /* ---- appointment filter + search ---- */
    var rows = $$('.pc-appt');
    var buttons = $$('.pc-filter');
    var search = $('#clSearch');
    var noResult = $('#clNoResult');
    var activeFilter = 'all';

    function applyFilters() {
        var q = search ? search.value.trim().toLowerCase() : '';
        var shown = 0;
        rows.forEach(function (el) {
            var okGroup = activeFilter === 'all' || el.getAttribute('data-group') === activeFilter;
            var okText = q === '' || el.textContent.toLowerCase().indexOf(q) !== -1;
            var show = okGroup && okText;
            el.style.display = show ? '' : 'none';
            if (show) { shown += 1; }
        });
        if (noResult) { noResult.classList.toggle('d-none', shown !== 0 || rows.length === 0); }
    }
    buttons.forEach(function (btn) {
        btn.addEventListener('click', function () {
            buttons.forEach(function (b) { b.classList.remove('active'); });
            btn.classList.add('active');
            activeFilter = btn.getAttribute('data-filter');
            applyFilters();
        });
    });
    if (search) { search.addEventListener('input', applyFilters); }

    /* ---- booking modal ---- */
    var form = $('#clBookForm');
    if (!form) { return; }
    var dateInput = $('#clDate'), slotInput = $('#clSlot');
    var sumDoc = $('#clSumDoc'), sumDate = $('#clSumDate');

    function pad(n) { return String(n).padStart(2, '0'); }
    function toDateStr(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
    dateInput.min = toDateStr(new Date());

    function updateSummary() {
        var checked = form.querySelector('input[name="doctor_id"]:checked');
        sumDoc.textContent = checked ? checked.getAttribute('data-name') : 'No doctor selected';
        if (slotInput.value) {
            sumDate.textContent = new Date(slotInput.value).toLocaleString([], {
                weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'
            });
        } else {
            sumDate.textContent = 'no time selected';
        }
    }
    form.addEventListener('change', updateSummary);
    if (window.ClinicSlotPicker) {
        window.ClinicSlotPicker({
            form: form, dateInput: dateInput, slotsBox: $('#clSlots'),
            hidden: slotInput, timeInput: $('#clTime'), onChange: updateSummary
        });
    }

    $$('[data-quick]', form).forEach(function (btn) {
        btn.addEventListener('click', function () {
            var d = new Date();
            var kind = btn.getAttribute('data-quick');
            if (kind === 'tomorrow') { d.setDate(d.getDate() + 1); }
            else if (kind === 'week') { d.setDate(d.getDate() + 7); }
            dateInput.value = toDateStr(d);
            dateInput.dispatchEvent(new Event('change', {bubbles: true}));
        });
    });

    /* "Book" next to a doctor pre-selects that doctor in the modal */
    $$('[data-doctor]').forEach(function (b) {
        b.addEventListener('click', function () {
            var radio = form.querySelector('input[name="doctor_id"][value="' + b.getAttribute('data-doctor') + '"]');
            if (radio) {
                radio.checked = true;
                radio.dispatchEvent(new Event('change', {bubbles: true}));
            }
        });
    });

    form.addEventListener('submit', function () {
        if (form.checkValidity()) {
            $('#clSubmit').disabled = true;
            $('#clSubmitText').textContent = 'Booking...';
        }
    });
})();
